function winCount(){var n=0;DAYS.forEach(function(d){W[d[0]].slots.forEach(function(x){if(x.done)n++;});W[d[0]].tasks.forEach(function(x){if(x.done)n++;});});return n;}
function dayProg(k){var s=W[k].slots.filter(function(x){return x.type!=="open";}),t=W[k].tasks;var done=s.filter(function(x){return x.done;}).length+t.filter(function(x){return x.done;}).length;return {done:done,total:s.length+t.length};}
function miniRing(p,col){var C=2*Math.PI*9;return '<svg width="24" height="24" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" fill="none" style="stroke:rgba(255,255,255,.1)" stroke-width="4"/><circle cx="12" cy="12" r="9" fill="none" style="stroke:'+col+'" stroke-width="4" stroke-linecap="round" stroke-dasharray="'+C.toFixed(1)+'" stroke-dashoffset="'+(C*(1-p)).toFixed(1)+'"/></svg>';}
function loadInfo(i){var k=DAYS[i][0],s=sorted(k).filter(function(x){return x.type!=="open";});var o={on:0,first:null,last:null,turn:null,big:false,short:false,late:false,empty:!s.length};
 if(!s.length)return o;s.forEach(function(x){o.on+=dur(x);});o.first=s[0].t;o.last=s.reduce(function(m,x){return mins(x.e)>mins(m)?x.e:m;},s[0].e);
 var pk=DAYS[(i+6)%7][0],ps=sorted(pk).filter(function(x){return x.type!=="open";});
 if(ps.length){var pl=ps.reduce(function(m,x){return mins(x.e)>mins(m)?x.e:m;},ps[0].e);o.turn=1440-mins(pl)+mins(o.first);}
 o.big=o.on>=360;o.short=o.turn!=null&&o.turn<600;o.late=mins(o.last)>mins(W.meta.wind);return o;}
function loadPills(i){var k=DAYS[i][0],L=loadInfo(i),h='<div class="lps">';
 if(L.empty)return h+(k==="sun"?'<span class="lp ok">Rest day · keep it free</span>':'<span class="lp">Free day</span>')+'</div>';
 h+='<span class="lp">'+nice(L.first)+' – '+nice(L.last)+'</span>';
 h+=L.big?'<span class="lp w">Big day · '+durTxt(L.on)+' on</span>':'<span class="lp ok">'+durTxt(L.on)+' on · balanced</span>';
 if(L.short)h+='<span class="lp w">Short night · '+durTxt(L.turn)+' since last finish</span>';
 if(L.late)h+='<span class="lp w">Runs past wind-down</span>';
 return h+'</div>';}
