var FX={c:null,p:[],raf:0};
function burst(x,y,cols,n,spread){if(!W.meta.fx)return;try{if(matchMedia("(prefers-reduced-motion: reduce)").matches)return;}catch(e){}
 if(!FX.c){FX.c=document.createElement("canvas");FX.c.id="fx";FX.c.setAttribute("aria-hidden","true");layer().appendChild(FX.c);}
 var c=FX.c,dpr=window.devicePixelRatio||1;if(c.width!==innerWidth*dpr){c.width=innerWidth*dpr;c.height=innerHeight*dpr;c.style.width=innerWidth+"px";c.style.height=innerHeight+"px";}
 for(var i=0;i<n;i++){var a=Math.random()*Math.PI*2,v=(1.5+Math.random()*5)*(spread||1);FX.p.push({x:x,y:y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-3,s:4+Math.random()*5,r:Math.random()*6,vr:(Math.random()-.5)*.5,c:cols[i%cols.length],l:55+Math.random()*35});}
 if(!FX.raf)FX.raf=requestAnimationFrame(step);}
function step(){var c=FX.c,x=c.getContext("2d"),dpr=window.devicePixelRatio||1;x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,innerWidth,innerHeight);
 FX.p=FX.p.filter(function(p){p.l--;p.vy+=.17;p.vx*=.985;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.globalAlpha=Math.max(0,Math.min(1,p.l/25));x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/4,p.s,p.s/2);x.restore();return p.l>0&&p.y<innerHeight+30;});
 if(FX.p.length)FX.raf=requestAnimationFrame(step);else{FX.raf=0;x.clearRect(0,0,innerWidth,innerHeight);}}
