var TRAILS=[{"id": "ourimbah-forest", "n": "Ourimbah State Forest – forest roads", "r": "Central Coast", "a": "Red Hill Road at Yarramalong Road, Ourimbah NSW", "g": "Road-registered bike and appropriate rider licence. Follow Forestry signs.", "c": "No riding fee published", "tt": "Open formed forest roads", "h": "Check forestry notices, gates and road condition.", "x": "Red Hill Road is the signed access from Yarramalong Road. Stay on roads open to motor vehicles. The mountain-bike park and its jumps are for bicycles.", "u": "https://www.forestrycorporation.com.au/visiting/forests/ourimbah-state-forest"}, {"id": "olney-forest", "n": "Olney State Forest – Watagan Forest Road", "r": "Central Coast / Lake Macquarie", "a": "Olney HQ, Watagan Forest Road, Olney State Forest NSW", "g": "Road-registered bike and appropriate rider licence. Use open formed roads.", "c": "No riding fee published", "tt": "Shared unsealed forest roads", "h": "Check Forestry notices and road signs. Wet conditions and washouts can close roads.", "x": "Start with the formed road network around Olney HQ and The Pines. Walking and picnic areas have separate access. Check Basin Forest Road status before using it.", "u": "https://www.forestrycorporation.com.au/visit/forests/olney-state-forest"}, {"id": "jilliby-sca", "n": "Jilliby State Conservation Area – designated roads", "r": "Central Coast", "a": "Jilliby Road and Watagan Forest Road, Jilliby NSW", "g": "Road-registered bike and appropriate rider licence. Use signed vehicle roads only.", "c": "No riding fee published", "tt": "Unsealed 4WD access roads", "h": "Gates and roads can close when wet or for fire danger. Check NPWS alerts.", "x": "NPWS lists the Jilliby Road approach, and alternative access from Ourimbah or Martinsville. Technical when wet.", "u": "https://www.nationalparks.nsw.gov.au/visit-a-park/parks/jilliby-state-conservation-area/visitor-info"}, {"id": "heaton-forest", "n": "Heaton State Forest – lookouts access", "r": "Newcastle and Hunter", "a": "Heaton Road, Brunkerville NSW, toward McLeans Lookout", "g": "Road-registered bike and appropriate rider licence. Follow Forestry signs.", "c": "No riding fee published", "tt": "Shared formed forest roads", "h": "Check Forestry notices before departure.", "x": "Use the Forestry map for Watagan Forest Road, Taylors Road and lookout roads. Logging traffic may share the roads.", "u": "https://www.forestrycorporation.com.au/__data/assets/pdf_file/0018/440181/heaton-sf-map.pdf"}, {"id": "watagans-np", "n": "Watagans National Park – vehicle roads", "r": "Lake Macquarie / Hunter", "a": "Mount Faulk Road at Freemans Drive, Cooranbong NSW", "g": "Road-registered bike and appropriate rider licence. Use open vehicle roads.", "c": "No riding fee published", "tt": "Unsealed roads, some 4WD-grade", "h": "Check NPWS alerts for Mount Faulk, Heaton and Watagan Forest Road approaches.", "x": "NPWS lists vehicle access from Mount Faulk Road, Martinsville and Heaton Road. Respect gates, signs and track-use restrictions.", "u": "https://www.nationalparks.nsw.gov.au/visit-a-park/parks/watagans-national-park/visitor-info"}, {"id": "worimi-rva", "n": "Stockton Bight – Worimi Recreational Vehicle Area", "r": "Newcastle and Port Stephens", "a": "Worimi Conservation Lands Lavis Lane entrance, Williamtown NSW", "g": "Eligible road-registered motorbike or approved Stockton conditional registration. WCL permit required. Check rider and vehicle eligibility.", "c": "WCL: $33 three-day or $88 annual beach vehicle permit. Annual conditional RVA permit $88, plus registration costs.", "tt": "Designated sand and dune riding area", "h": "Conditional vehicles use the Lavis Lane entry and daylight hours. Check tide, closures and current conditions.", "x": "Use the signed RVA and legal access corridors. The dunes are a shared vehicle area. No authorised jump facility identified. Conditional rego is site-specific.", "u": "https://worimiconservationlands.com/beach-driving/"}, {"id": "howes-trail", "n": "Howes Trail – Yengo National Park", "r": "Sydney fringe / Hunter", "a": "Howes Trail off Putty Road, Howes Valley NSW", "g": "Road-registered bike and appropriate rider licence. Follow NPWS road restrictions.", "c": "No riding fee published for this route", "tt": "30 km touring route. Rough and eroded sections.", "h": "Check route alerts. NPWS has flagged rough sections between Putty Road and Yango Track.", "x": "NPWS identifies this as a route used by motorbikes. Access from Howes Valley or Laguna via Yango Creek Road and Finchley Track. For experienced riders when rough.", "u": "https://www.nationalparks.nsw.gov.au/things-to-do/4wd-touring-routes/howes-trail/visitor-info"}, {"id": "burralow-road", "n": "Burralow Creek vehicle approach", "r": "Sydney fringe / Blue Mountains", "a": "Paterson Range fire trail off Bells Line of Road, Bilpin NSW", "g": "Road-registered bike and appropriate rider licence. Ride only the open vehicle approach.", "c": "No riding fee published. Camp booking fee $6 if staying.", "tt": "Unsealed, 4WD-grade vehicle approach", "h": "Weather-dependent. Check local alerts and vehicle access at the gate.", "x": "NPWS also lists access from Kurrajong via Burralow Road and Tabaraga Ridge fire trail. Use signed vehicle roads and stay off the walking routes.", "u": "https://www.nationalparks.nsw.gov.au/camping-and-accommodation/campgrounds/burralow-creek-campground-picnic-area/visitor-info"}, {"id": "gardens-of-stone", "n": "Gardens of Stone State Conservation Area – designated vehicle roads", "r": "Sydney fringe / Lithgow", "a": "Old Bells Line of Road at Zig Zag Railway, Clarence NSW", "g": "Road-registered bike and appropriate rider licence. Designated formed roads and trails only.", "c": "No riding fee published", "tt": "Unsealed 4WD roads", "h": "Multiple roadworks and closures can affect access. Read park alerts and use the latest map.", "x": "Official brochure lists Old Bells Line of Road and Glow Worm Tunnel Road access. Turn back at closures and avoid tracks marked for walking or cycling.", "u": "https://www.nationalparks.nsw.gov.au/-/media/visitor/files/pdf/brochures/gardens-of-stone-sca-print-brochure-october-2023.pdf"}];
