function money(n){return "$"+(Math.round(n*100)/100).toLocaleString("en-AU",{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2});}
function todayISO(){var d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function niceDate(s){var d=new Date(s+"T12:00");return d.toLocaleDateString("en-AU",{weekday:"short",day:"numeric",month:"short"});}
function toast(t){var el=$("toast");el.textContent=t;el.classList.add("on");clearTimeout(toast.h);toast.h=setTimeout(function(){el.classList.remove("on");},1800);}

