var D=null,PULLED=false,PT=null;
function boot(){if(D)return;try{D=JSON.parse(localStorage.getItem(KEY)||"null");}catch(e){D=null;}if(!D||!D.bike)D=JSON.parse(JSON.stringify(D0));pullDb();}
function pullDb(){if(!isHer())return;sb.from("sarsha_husky").select("data").eq("user_id",SID).maybeSingle().then(function(r){PULLED=true;if(r&&r.data&&r.data.data&&r.data.data.bike){D=r.data.data;try{localStorage.setItem(KEY,JSON.stringify(D));}catch(e){}if(typeof view!=="undefined"&&view==="husky"&&!(SR&&SR.getElementById("sheet")&&SR.getElementById("sheet").classList.contains("on")))render();}else pushDb();}).catch(function(){PULLED=true;});}
function pushDb(){if(!isHer()||!PULLED)return;clearTimeout(PT);PT=setTimeout(function(){sb.from("sarsha_husky").upsert({user_id:SID,data:D,updated_at:new Date().toISOString()}).then(function(r){if(r&&r.error)console.warn("husky save",r.error.message);});},700);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(D));}catch(e){}pushDb();}

