var SYD=["Greater Sydney","Blue Mountains and Lithgow","Illawarra and South Coast"];
var ROrder=["Central Coast","Lake Macquarie","Newcastle and Hunter","Greater Sydney","Blue Mountains and Lithgow","Illawarra and South Coast"];
function rIdx(r){var i=ROrder.indexOf(r);return i<0?9:i;}
function storeById(id){return STORES.filter(function(s){return s.id===id;})[0];}
function trackById(id){return TRACKS.filter(function(s){return s.id===id;})[0];}
function vidById(id){return VIDEOS.filter(function(v){return v.id===id;})[0];}
