/* bike */
R.bike=function(){
  var b=D.bike,ok=b.trimOk;
  var h=back("hub","Husky 125")+'<div class="ph"><h2>My <span>bike</span></h2><small>'+b.year+' '+b.make+'</small></div>'+
  '<div class="it"><h3>'+b.year+' '+b.make+' '+E(b.trim)+'</h3><div class="tags">'+(ok?'<span class="tag ok">Trim confirmed</span>':'<span class="tag warn">Trim to confirm</span>')+'<span class="tag gold">Year: from Jake</span><span class="tag">Two-stroke · Mikuni TMX 38</span></div>'+
  (ok?'':'<div class="note">Check the model label on the frame, your dealer paperwork, or ask a Husqvarna dealer to look it up by VIN. Specs below are from the 2021 TC 125 manual and only apply once you confirm.</div><div class="acts"><button class="btn p" onclick="HK.confirmTrim(true)">Yes, it\'s a TC 125</button><button class="btn" onclick="HK.confirmTrim(false)">It\'s something else</button></div>')+
  '<div class="two" style="margin-top:12px"><div class="f"><label>Hour meter now</label><input id="bH" inputmode="decimal" value="'+E(b.hours)+'" placeholder="e.g. 41.6" onchange="HK.D.bike.hours=this.value.trim();HK.save();HK.toast(\'Hours saved\')"></div><div class="f"><label>Registration</label><select onchange="HK.D.bike.rego=this.value;HK.save();HK.render()"><option value="none"'+(b.rego==="none"?' selected':'')+'>Not registered</option><option value="cond"'+(b.rego==="cond"?' selected':'')+'>Conditional (Stockton)</option><option value="full"'+(b.rego==="full"?' selected':'')+'>Road registered</option></select></div></div></div>';
  h+='<div class="lab">Premix · 40:1</div><div class="it"><div class="mix"><div><input id="mxL" type="number" min="0" step="0.5" value="5" oninput="HK.mix()" aria-label="Litres of petrol"><small>Litres of 98</small></div><span class="muted">→</span><div><output id="mxO">125 mL</output><small>Two-stroke oil</small></div></div><div class="note">25 mL of JASO FD two-stroke oil per litre of 98 RON. '+(ok?'From the 2021 TC 125 manual.':'From the 2021 TC 125 manual · confirm your trim first.')+'</div></div>';
  h+='<div class="lab">Quick specs'+(ok?'':' · TC 125, once confirmed')+'</div><div class="spec" style="'+(ok?'':'opacity:.6')+'">'+
   '<div><small>Gearbox oil</small><b>0.8 L</b><em>SAE 15W/50 · change fill, check cold</em></div>'+
   '<div><small>Spark plug</small><b>NGK BR9 ECMVX</b><em>0.60 mm gap</em></div>'+
   '<div><small>Tyres</small><b>1.0 bar</b><em>about 15 psi front and rear</em></div>'+
   '<div><small>Fuel</small><b>98 RON</b><em>premix 40:1</em></div></div>';
  h+='<div class="lab">Care list · '+CARE.length+' jobs</div>'+CARE.map(function(c){return '<details class="care"><summary><div><b>'+E(c.j)+'</b><small>'+E(c.w)+'</small></div><span class="tag '+(/workshop/i.test(c.k)?'warn':/basic/i.test(c.k)?'ok':'')+'">'+E(c.k)+'</span></summary><div class="in">'+E(c.h)+'<a class="src" href="'+E(c.u)+'" target="_blank" rel="noopener">Manual · '+E(c.s)+' ›</a></div></details>';}).join("");
  h+='<div class="note">Workshop jobs (brakes, cooling, suspension, jetting, top end) go to a qualified mechanic. Husqvarna parts and service near you are tagged in Stores.</div><div class="acts"><button class="btn" onclick="HK.go(\'stores\',{store:{q:\'\',reg:\'All\',cat:\'\',husky:true}})">Husqvarna parts ›</button><button class="btn" onclick="HK.go(\'videos\',{vid:\'Maintenance\'})">Maintenance videos ›</button></div>';
  return h;
};
function confirmTrim(y){if(y){D.bike.trimOk=true;save();render();toast("TC 125 confirmed");}else{openSheet('<h3>What model is it?</h3><div class="f"><label>Model on the frame label or paperwork</label><input id="tmIn" placeholder="e.g. TE 150, TC 85"></div><div class="hint">The quick specs are for the 2021 TC 125, so they stay greyed out for other models.</div><div style="height:10px"></div><button class="btn p big" onclick="HK.saveTrim()">Save</button>');}}
function saveTrim(){var t=(($("tmIn")||{}).value||"").trim();if(!t){toast("Type the model");return;}D.bike.trim=t;D.bike.trimOk=/^tc ?125$/i.test(t);D.bike.other=!D.bike.trimOk;save();closeSheet();render();toast("Saved");}
function mix(){var l=parseFloat($("mxL").value)||0;$("mxO").textContent=Math.round(l*25)+" mL";}

/* stores */
R.stores=function(){
  var f=V.store,q=f.q.toLowerCase();
  var list=STORES.filter(function(s){
    if(f.husky&&HUSKY_STORES.indexOf(s.id)<0)return false;
    if(f.reg==="Near home"&&NEAR.indexOf(s.r)<0)return false;
    if(f.reg!=="Near home"&&f.reg!=="All"&&s.r!==f.reg)return false;
    if(f.cat&&storeCats(s).indexOf(f.cat)<0)return false;
    if(q&&(s.n+" "+s.s+" "+s.a).toLowerCase().indexOf(q)<0)return false;
    return true;
  }).sort(function(a,b){return rIdx(a.r)-rIdx(b.r)||a.n.localeCompare(b.n);});
  var h=back("hub","Husky 125")+'<div class="ph"><h2><span>Stores</span></h2><small>'+STORES.length+' in NSW</small></div>'+
  '<input class="search" type="search" placeholder="Search shop or suburb" value="'+E(f.q)+'" oninput="HK.V.store.q=this.value;HK.renderList()">'+
  '<div class="chips">'+["Near home","Central Coast","Lake Macquarie","Newcastle and Hunter","Greater Sydney","All"].map(function(r){return '<button class="chip'+(f.reg===r?' on':'')+'" onclick="HK.V.store.reg=\''+r+'\';HK.render()">'+r.replace("Newcastle and Hunter","Newcastle & Hunter")+'</button>';}).join("")+'</div>'+
  '<div class="chips"><button class="chip gold'+(f.husky?' on':'')+'" onclick="HK.V.store.husky=!HK.V.store.husky;HK.render()">Husqvarna parts</button>'+["Bikes","Parts","Gear","Tyres","Service"].map(function(c){return '<button class="chip gold'+(f.cat===c?' on':'')+'" onclick="HK.V.store.cat=HK.V.store.cat===\''+c+'\'?\'\':\''+c+'\';HK.render()">'+c+'</button>';}).join("")+'</div>'+
  '<div id="list">'+storeList(list)+'</div>';
  return h;
};
function storeList(list){
  return '<div class="count">'+list.length+' shop'+(list.length===1?'':'s')+'</div>'+(list.length?list.map(storeCard).join(""):'<div class="note">Nothing matches. Try All regions or clear a filter.</div>');
}
function renderList(){var el=$("list");if(!el)return;var keep=V.store;V.view="stores";var tmp=document.createElement("div");tmp.innerHTML=R.stores();el.innerHTML=tmp.querySelector("#list").innerHTML;}
function storeCard(s){
  var firm=hoursFirm(s),hk=HUSKY_STORES.indexOf(s.id)>=0;
  return '<div class="it"><h3>'+E(s.n)+'</h3><div class="sub">'+E(s.s)+' · '+E(s.r)+'</div>'+
  '<div class="tags">'+storeCats(s).map(function(c){return '<span class="tag">'+c+'</span>';}).join("")+(hk?'<span class="tag hk">Husqvarna</span>':'')+(firm?'':'<span class="tag warn">Confirm hours</span>')+'</div>'+
  '<dl class="kv"><dt>Address</dt><dd>'+E(s.a)+'</dd><dt>Hours</dt><dd>'+E(s.h)+(firm?'':' <span class="muted">('+E(s.ev.toLowerCase())+' listing)</span>')+'</dd>'+(s.p?'<dt>Phone</dt><dd><a href="tel:'+s.p.replace(/\s/g,"")+'">'+E(s.p)+'</a></dd>':'')+'</dl>'+
  '<div class="note">'+E(s.x)+'</div>'+
  '<div class="acts"><a class="btn p" href="'+maps(s.n,s.a)+'" target="_blank" rel="noopener">Open in Maps</a><a class="btn" href="'+E(s.u)+'" target="_blank" rel="noopener">Website</a>'+(s.p?'<a class="btn" href="tel:'+s.p.replace(/\s/g,"")+'">Call</a>':'')+'<button class="btn" onclick="HK.spendSheet(\''+s.id+'\')">+ Log spend</button></div></div>';
}

/* tracks */
function trackSort(a,b){var pin=["ranch-mx","appin-mx"];var pa=pin.indexOf(a.id),pb=pin.indexOf(b.id);if(pa<0)pa=9;if(pb<0)pb=9;if(pa!==pb)return pa-pb;
  var va=a.v==="Confirm before travel"?1:0,vb=b.v==="Confirm before travel"?1:0;return rIdx(a.r)-rIdx(b.r)||va-vb||a.n.localeCompare(b.n);}
var TF=[["pub","Public ride days",function(t){return /public/i.test(t.ac);}],["club","Club events",function(t){return /club|member|event/i.test(t.ac+" "+t.tt);}],["jr","Junior",function(t){return /junior|nipper/i.test(t.n+" "+t.ac+" "+t.f+" "+t.x+" "+t.tt);}],["beg","Beginner practice",function(t){return /novice|beginner/i.test(t.x);}],["fee","Published fee",function(t){return t.pt==="Published ride fee";}],["saved","Saved",function(t){return D.saved.indexOf(t.id)>=0;}]];
R.tracks=function(){
  var f=V.track;
  var h=back("hub","Husky 125")+'<div class="ph"><h2><span>Tracks</span></h2><small>'+TRACKS.length+' MX · '+TRAILS.length+' public trails</small></div>'+
  '<div class="seg"><button class="'+(f.mode==="mx"?'on':'')+'" onclick="HK.V.track.mode=\'mx\';HK.render()">MX tracks</button><button class="'+(f.mode==="trail"?'on':'')+'" onclick="HK.V.track.mode=\'trail\';HK.render()">Public trail roads</button></div>';
  if(f.mode==="trail")return h+trailsView();
  var list=TRACKS.filter(function(t){
    if(f.reg==="Near home"&&NEAR.indexOf(t.r)<0&&["ranch-mx","appin-mx"].indexOf(t.id)<0)return false;
    if(f.reg==="Sydney side"&&SYD.indexOf(t.r)<0)return false;
    if(f.reg==="Regional NSW"&&(NEAR.indexOf(t.r)>=0||SYD.indexOf(t.r)>=0))return false;
    for(var i=0;i<TF.length;i++)if(f.f[TF[i][0]]&&!TF[i][2](t))return false;
    return true;
  }).sort(trackSort);
  h+='<div class="chips">'+["Near home","Sydney side","Regional NSW","All"].map(function(r){return '<button class="chip'+(f.reg===r?' on':'')+'" onclick="HK.V.track.reg=\''+r+'\';HK.render()">'+r+'</button>';}).join("")+'</div>'+
  '<div class="chips">'+TF.map(function(x){return '<button class="chip gold'+(f.f[x[0]]?' on':'')+'" onclick="HK.V.track.f.'+x[0]+'=!HK.V.track.f.'+x[0]+';HK.render()">'+x[1]+'</button>';}).join("")+'</div>'+
  '<div class="count">'+list.length+' track'+(list.length===1?'':'s')+(f.reg==="Near home"?' · Ranch MX and Appin pinned':'')+'</div>'+
  (list.length?list.map(trackCard).join(""):'<div class="note">Nothing matches. Try All or clear a filter.</div>')+
  '<details class="care" style="margin-top:14px"><summary><div><b>Held back · '+HELD.length+' leads</b><small>Not shown as places to ride until checked</small></div><span class="tag">Why</span></summary><div class="in">'+HELD.map(function(k){return E(k.n)+' <span class="muted">· '+E(k.d)+'</span>';}).join("<br>")+'</div></details>';
  return h;
};
function trackCard(t){
  var sv=D.saved.indexOf(t.id)>=0;
  var vt=t.v==="Published access"?'<span class="tag ok">Published access</span>':t.v==="Event schedule"?'<span class="tag hk">Check calendar</span>':'<span class="tag warn">Confirm before travel</span>';
  var pt=t.pt==="Published ride fee"?'<span class="tag ok">$'+t.ad+' adult</span>':t.pt==="Past event example"?'<span class="tag warn">Past event example</span>':t.pt==="Membership only"?'<span class="tag">Membership</span>':'<span class="tag">Confirm fee</span>';
  return '<div class="it" style="border-left:3px solid '+(t.v==="Published access"?'var(--ok)':t.v==="Event schedule"?'var(--hk)':'var(--warn)')+'"><h3>'+E(t.n)+'</h3><div class="sub">'+E(t.t)+' · '+E(t.r)+'</div>'+
  '<div class="tags">'+vt+pt+'<span class="tag">'+E(t.tt)+'</span></div>'+
  '<dl class="kv"><dt>Access</dt><dd>'+E(t.ac)+'</dd><dt>When</dt><dd>'+E(t.h)+'</dd><dt>Fee</dt><dd>'+E(t.f)+'</dd><dt>Address</dt><dd>'+E(t.a)+'</dd></dl>'+
  '<div class="note">'+E(t.x)+'</div>'+
  '<div class="acts"><button class="btn'+(sv?' on':'')+'" onclick="HK.togSave(\''+t.id+'\')">'+(sv?'★ Saved':'☆ Save')+'</button><button class="btn p" onclick="HK.rideSheet(\''+t.id+'\')">Log a ride</button><a class="btn" href="'+maps(t.n,t.a)+'" target="_blank" rel="noopener">Maps</a><a class="btn" href="'+E(t.u)+'" target="_blank" rel="noopener">Website</a></div></div>';
}
function togSave(id){var i=D.saved.indexOf(id);if(i<0)D.saved.push(id);else D.saved.splice(i,1);save();render();toast(i<0?"Saved":"Removed");}
function trailsView(){
  var reg=D.bike.rego;
  var h='';
  if(reg==="none")h+='<div class="banner"><b>Your bike can\'t ride these yet</b>A TC 125 is a closed-course competition bike. Every trail here needs a road-registered bike and a rider licence. Until then, ride at an MX track.<div class="acts"><button class="btn p" onclick="HK.V.track.mode=\'mx\';HK.render()">Show MX tracks ›</button><button class="btn" onclick="HK.go(\'bike\')">Change rego in My Bike</button></div></div>';
  else if(reg==="cond")h+='<div class="banner hk"><b>Conditional rego</b>Stockton conditional rego is site-specific. It covers the Worimi riding area only, not the forest roads below.</div>';
  else h+='<div class="banner ok"><b>Road registered</b>Formed roads open to vehicles only. Check closures before you go.</div>';
  h+='<div class="note" style="margin:0 0 10px">No public jumps. Jumps are only at MX tracks. Mountain-bike park jumps are for bicycles.</div>';
  var stock=TRAILS.filter(function(t){return t.id==="worimi-rva";})[0];
  TRAILS.filter(function(t){return t!==stock;}).forEach(function(t){h+=trailCard(t,reg==="full");});
  if(stock){h+='<div class="lab">Separate permit · Stockton</div>'+trailCard(stock,reg!=="none",true);}
  return h;
}
function trailCard(t,canMap,permit){
  return '<div class="it" style="border-left:3px solid '+(permit?'var(--gold)':'var(--line2)')+'"><h3>'+E(t.n)+'</h3><div class="sub">'+E(t.r)+' · '+E(t.tt)+'</div>'+
  '<dl class="kv"><dt>Rego + licence</dt><dd>'+E(t.g)+'</dd><dt>Closures</dt><dd>'+E(t.h)+'</dd><dt>Cost</dt><dd>'+E(t.c)+'</dd><dt>Start at</dt><dd>'+E(t.a)+'</dd></dl>'+
  '<div class="note">'+E(t.x)+'</div>'+
  '<div class="acts"><a class="btn" href="'+E(t.u)+'" target="_blank" rel="noopener">Alerts + rules</a><a class="btn p" href="'+maps(t.n,t.a)+'" target="_blank" rel="noopener"'+(canMap?'':' aria-disabled="true" tabindex="-1"')+'>'+(canMap?'Open in Maps':'Maps · needs rego')+'</a></div></div>';
}

/* videos */
var VCOL={"Riding Tips":"#7cb8ff","Riding Tricks":"#e277c4","Maintenance":"#c99a5b"};
R.videos=function(){
  var sec=V.vid,lr=lastRide(),sg=lr?lessonsFor(lr.struggle):[];
  var h=back("hub","Husky 125")+'<div class="ph"><h2><span>Videos</span></h2><small>'+VIDEOS.length+' picked for your bike</small></div>'+
  '<div class="seg">'+["Riding Tips","Riding Tricks","Maintenance"].map(function(s){return '<button class="'+(sec===s?'on':'')+'" onclick="HK.V.vid=\''+s+'\';HK.render()">'+s.replace("Riding ","")+'</button>';}).join("")+'</div>';
  var list=VIDEOS.filter(function(v){return v.sec===sec;});
  if(sec==="Riding Tips"&&sg.length)h+=suggBox(lr,sg);
  if(sec==="Riding Tricks")h+='<div class="note" style="margin:0 0 10px">Small jumps and tabletops first, on a coached day. The brake-tap lesson is for later, with a coach.</div>';
  if(sec==="Maintenance"){
    h+='<div class="chips"><button class="chip gold'+(V.maint==="routine"?' on':'')+'" onclick="HK.V.maint=\'routine\';HK.render()">Routine care</button><button class="chip gold'+(V.maint==="workshop"?' on':'')+'" onclick="HK.V.maint=\'workshop\';HK.render()">Workshop</button></div>';
    list=list.filter(function(v){return V.maint==="workshop"?v.l==="Workshop":v.l!=="Workshop";});
    h+='<div class="note" style="margin:0 0 10px">'+(V.maint==="workshop"?'For knowing what the mechanic does. Settings and parts come from the 2021 TC 125 manual or your dealer.':'General methods. Use the 2021 TC 125 manual for specs, fills and torques.')+'</div>';
  }
  h+=list.map(function(v){
    var coach=/coach/i.test(v.l)||/coach/i.test(v.c);
    var ref=/reference/i.test(v.hd);
    return '<div class="vid"><a class="vthumb" style="--vc:'+VCOL[v.sec]+'" href="'+yt(v.id)+'" target="_blank" rel="noopener" aria-label="Play '+E(v.t)+' on YouTube"><span>'+E(v.top.split(/[ ,]/)[0])+'</span></a><div><h3>'+E(v.t)+'</h3><div class="sub">'+E(v.w)+(v.ch&&v.ch!==v.w?' · '+E(v.ch):'')+'</div>'+
    '<div class="tags" style="margin-top:5px"><span class="tag">'+E(v.l)+'</span>'+(coach?'<span class="tag warn">With a coach</span>':'')+(sec==="Maintenance"?'<span class="tag '+(ref?'warn':'')+'">'+E(v.fit)+'</span>':'')+'</div>'+
    '<p>'+E(v.c)+'</p><div class="acts" style="margin-top:7px"><a class="btn p" href="'+yt(v.id)+'" target="_blank" rel="noopener">Open on YouTube</a></div></div></div>';
  }).join("");
  return h;
};

